    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261018180122_InitialLocalJobsRedesign') THEN
    CREATE TABLE "Ads" (
        "Id" uuid NOT NULL,
        "Title" character varying(120) NOT NULL,
        "Description" character varying(3000) NOT NULL,
        "AdCategoryId" integer NOT NULL,
        "CityId" integer NOT NULL,
        "Price" numeric(18,2),
        "UserId" uuid NOT NULL,
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Ads" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Ads_AdCategories_AdCategoryId" FOREIGN KEY ("AdCategoryId") REFERENCES "AdCategories" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Ads_Cities_CityId" FOREIGN KEY ("CityId") REFERENCES "Cities" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Ads_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261018180122_InitialLocalJobsRedesign') THEN
    CREATE TABLE "Jobs" (
        "Id" uuid NOT NULL,
        "Title" character varying(100) NOT NULL,
        "Description" character varying(2000) NOT NULL,
        "Salary" numeric(18,2),
        "PaymentPeriod" character varying(20) NOT NULL DEFAULT 'Monthly',
        "WorkType" character varying(50) NOT NULL DEFAULT '',
        "ExperienceRequirement" character varying(200) NOT NULL DEFAULT '',
        "StartDate" timestamp with time zone,
        "CategoryId" integer NOT NULL,
        "CityId" integer NOT NULL,
        "UserId" uuid NOT NULL,
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Jobs" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Jobs_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Jobs_Cities_CityId" FOREIGN KEY ("CityId") REFERENCES "Cities" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Jobs_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

