DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261018180122_InitialLocalJobsRedesign') THEN
    PERFORM setval(
        pg_get_serial_sequence('"AdCategories"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "AdCategories") + 1,
            nextval(pg_get_serial_sequence('"AdCategories"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Categories"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Categories") + 1,
            nextval(pg_get_serial_sequence('"Categories"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Cities"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Cities") + 1,
            nextval(pg_get_serial_sequence('"Cities"', 'Id'))),
        false);
    END IF;
END $EF$;

